//! Real art for catalog objects: `assets/models/objects/<object id>.glb` (generated by
//! `assets/blender/make_objects.py`, embedded by `build.rs`). An object with a model is drawn from
//! it; its RON `parts` still define picking and are the fallback when no model loads.
//!
//! Model space matches the parts: x across the footprint width, z across its depth (front +z),
//! y up, origin at the footprint's back-left corner on the floor. Each glTF material becomes one
//! draw with its base colour, roughness, metallic and emission; a material named after a
//! `materials.ron` id (Blender `.001` suffixes ignored) is also textured, its colour a tint.

use hearth_render::Renderer;
use hearth_render::model::{StaticPart, load_static_glb};
use sim::data::GameData;

include!(concat!(env!("OUT_DIR"), "/object_models.rs"));

/// Decodes every embedded model whose id is a defined object.
pub fn load(data: &GameData) -> Vec<(&'static str, Vec<StaticPart>)> {
    let mut out = Vec::new();
    for &(id, bytes) in OBJECT_MODELS {
        if !data.objects.iter().any(|o| o.id == id) {
            log::warn!("assets/models/objects/{id}.glb has no object in objects.ron; ignored");
            continue;
        }
        match load_static_glb(bytes) {
            Ok(parts) => out.push((id, parts)),
            Err(e) => log::warn!("object model {id}: {e:#}; using greybox parts"),
        }
    }
    out
}

/// Uploads the object models; [`crate::scene::object_draws`] finds them by object id.
pub fn install(r: &mut Renderer, data: &GameData) {
    let models = load(data);
    log::info!("object models: {} of {} objects", models.len(), data.objects.len());
    for (id, parts) in models {
        r.add_model(id, &parts);
    }
}

#[cfg(test)]
mod tests {
    use sim::data::GameData;

    #[test]
    fn embedded_models_decode_and_match_objects() {
        let data = GameData::embedded();
        let models = super::load(&data);
        assert_eq!(models.len(), super::OBJECT_MODELS.len(), "every model decodes and names an object");
        for (id, parts) in &models {
            let def = data.objects.iter().find(|o| o.id == *id).unwrap();
            let (w, d) = (def.footprint.0 as f32, def.footprint.1 as f32);
            for p in parts {
                for v in &p.mesh.vertices {
                    let [x, y, z] = v.pos;
                    assert!((-0.05..=w + 0.05).contains(&x) && (-0.05..=d + 0.05).contains(&z) && y >= -0.01, "{id}: vertex {:?} outside its {w}x{d} footprint", v.pos);
                }
                if !p.material.is_empty() && data.materials.iter().all(|m| m.id != p.material) {
                    // plain colour materials are fine; just make sure typos of texture ids are not silent
                    assert!(!data.materials.iter().any(|m| p.material.starts_with(&m.id)), "{id}: material {} looks like a misspelt texture id", p.material);
                }
            }
        }
    }
}
